PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE src_quests (
  id      INTEGER NOT NULL,
  who     TEXT    NOT NULL,           -- 回報的人的代號（站長自己記的是 owner）
  faction TEXT    NOT NULL DEFAULT '',-- Alliance／Horde（那一筆 S1 的陣營）
  plv     INTEGER,                    -- 這個人看到任務說明時的等級（取最低）
  at      INTEGER NOT NULL,
  PRIMARY KEY (id, who)
);
